    }
  }, true);

  function boot() {
    fixGlobalRacingReadMore();
    fixRemainingGoodyearAnchors();
    initCarousels();
    window.setTimeout(function () {
      fixGlobalRacingReadMore();
      fixRemainingGoodyearAnchors();
      initCarousels();
    }, 300);
    window.setTimeout(function () {
      fixGlobalRacingReadMore();
      fixRemainingGoodyearAnchors();
      initCarousels();
    }, 1200);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
